// Familiar application context, reconstructed from the supplied rendered HTML.
function appIcon(name){const paths={reset:'M5 8a8 8 0 1 1-1 7 M5 3v5H0',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 6v6l4 2',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',music:'M9 18V5l11-2v13 M9 7l11-2 M9 18c0 4-6 4-6 1s6-4 6-1 M20 16c0 4-6 4-6 1s6-4 6-1',mic:'M9 3h6v10a3 3 0 0 1-6 0z M5 10v3a7 7 0 0 0 14 0v-3 M12 20v2',record:'M7 7a7 7 0 0 0 0 10 M17 7a7 7 0 0 1 0 10 M4 4a11 11 0 0 0 0 16 M20 4a11 11 0 0 1 0 16 M12 9v6',check:'M4 4h16v16H4z M7 11l4 4 6-8',chart:'M4 3v18h18 M8 15V9 M13 17V5 M18 17v-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 1v3 M12 20v3 M1 12h3 M20 12h3 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',exit:'M9 3H3v18h6 M10 12h11 M17 8l4 4-4 4',chat:'M3 4h18v13H8l-5 4z',pdf:'M5 2h9l5 5v15H5z M14 2v6h5 M8 15h8 M12 11v8',cup:'M4 8h13v7a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5z M17 9h2a3 3 0 0 1 0 6h-2 M7 2v3 M12 2v3'};return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;}
function appSidebar(){return `<aside class="app-sidebar" lang="en" aria-label="Application navigation"><div class="app-brand"><span>MD</span><b>MandoCues</b></div><nav>${[['grid','Dashboard'],['music','Cues'],['mic','Sessions'],['record','Recording'],['check','Tasks'],['chart','Stats'],['settings','Settings']].map(([icon,label])=>`<button ${label==='Recording'?'aria-current="page"':'disabled'} title="${label}">${appIcon(icon)}<span>${label}</span></button>`).join('')}</nav><footer><button disabled>${appIcon('sun')}<span>Toggle theme</span></button><button disabled>${appIcon('exit')}<span>Sign out</span></button><div class="app-account"><i>F</i><div>Floris Heemskerk<small>florisheemskerk01@gmail.com</small></div></div></footer></aside>`;}
function proposalMusicSeconds(s){return (s===unifiedState?cues:s.sessionCues||cues).reduce((sum,c)=>{const [minutes,seconds]=c[2].split(':').map(Number);return sum+minutes*60+seconds;},0);}
function proposalMusicUsage(s){const used=proposalMusicSeconds(s),limit=(s.maxMusicMinutes??60)*60;return `<small data-music-usage class="session-music-usage ${used>limit?'is-over':''}" aria-label="Scheduled music ${time(used)} of ${time(limit)}">${time(used)} / ${time(limit)}</small>`;}
function syncMusicUsage(s){document.querySelectorAll('[data-music-usage]').forEach(el=>{const used=proposalMusicSeconds(s),limit=(s.maxMusicMinutes??60)*60;el.textContent=time(used)+' / '+time(limit);el.classList.toggle('is-over',used>limit);el.setAttribute('aria-label','Scheduled music '+time(used)+' of '+time(limit));});}
function proposalSessionFields(s){return `<div class="session-timing-fields"><label>Session length (min)<span><input data-session-setting="length" type="number" min="15" max="1440" step="1" value="${s.booked}"><small data-session-hours>${Math.floor(s.booked/60)}h ${String(s.booked%60).padStart(2,'0')}m</small></span></label><label>Prep per cue (min)<span><input data-session-setting="prep" type="number" min="0" max="60" value="${s.prepMinutes??3}"></span></label><label>Max music (min)<span><input data-session-setting="music" type="number" min="0" max="1440" value="${s.maxMusicMinutes??60}" aria-label="Maximum minutes of music">${proposalMusicUsage(s)}</span></label></div>`;}
function proposalSessionActions(s){return `<div class="session-app-actions"><button data-app-action="add-cues">+ Add cues</button><button data-app-action="chat" aria-pressed="${!!s.chatOpen}">${appIcon('chat')} Chat</button><details class="session-pdf-menu"><summary>${appIcon('pdf')} PDF <span>⌄</span></summary><div><small>Export</small><button data-app-export="order">Recording order</button><button data-app-export="takes">Take sheet (for the mixer)</button></div></details></div>`;}
function proposalSessionHeader(s){return `<section class="proposal-session-header" aria-label="Recording session"><div class="session-choice"><select data-session-select aria-label="Recording day" ${running(s)?'disabled':''}>${proposalSessionCatalog.map(day=>`<option value="${day.id}" ${day.id===s.sessionId?'selected':''}>${day.label}</option>`).join('')}</select><span>${proposalSessionMeta(s).detail}</span>${mainPanelLayout==='B'?proposalSessionActions(s):''}</div>${mainPanelLayout==='A'?`<div class="session-setup">${proposalSessionFields(s)}${proposalSessionActions(s)}</div>`:''}</section>`;}
function proposalPlanning(s){
 const timing=scoreWorkflowTiming(s),value=proposalClockTime(timing.clock.plannedEndAt);
 return `<details class="session-planning-menu" ${s.planningOpen?'open':''}><summary>${appIcon('clock')} Planning <span aria-hidden="true">⌄</span></summary><div class="session-planning-panel"><label class="planning-finish">Finish by<input type="text" data-planning-finish placeholder="05:30 PM" value="${value}" aria-label="Planned session end time"></label>${mainPanelLayout==='B'?proposalSessionFields(s):''}<div class="planning-extend"><span>Extend end</span>${[15,30,60].map(n=>`<button type="button" data-extend-session="${n}">+${n} min</button>`).join('')}</div><div class="planning-metrics"><label>Session work<b data-proposal-elapsed>${proposalDuration(timing.elapsed)}</b></label><label>Time left<b data-proposal-remaining>${proposalDuration(timing.remaining)}</b></label><label>Planned end<b data-proposal-planned-end>${proposalEndTime(timing,false)}</b></label><label>Projected end<b data-proposal-projected-end>${proposalEndTime(timing,true)}</b></label></div></div></details>`;
}
function positionPlanningMenu(){const menu=document.querySelector('.session-planning-menu[open]');if(!menu)return;const panel=menu.querySelector('.session-planning-panel'),r=menu.querySelector('summary').getBoundingClientRect();Object.assign(panel.style,{left:Math.max(8,Math.min(innerWidth-panel.offsetWidth-8,r.left))+'px',top:Math.min(r.bottom+8,Math.max(8,innerHeight-panel.offsetHeight-8))+'px'});}
function setProposalBudget(s,minutes){const timing=scoreWorkflowTiming(s),anchor=timing.clock.plannedEndAt-timing.clock.booked*1000;s.booked=minutes;timing.clock.booked=minutes*60;timing.clock.plannedEndAt=anchor+minutes*60000;timing.clock.fixedEndAt=s.sessionStarted?timing.clock.plannedEndAt:null;syncPlanningInputs(s);}
function syncPlanningInputs(s){const timing=scoreWorkflowTiming(s),end=new Date(timing.clock.plannedEndAt);document.querySelectorAll('[data-session-setting="length"]').forEach(el=>el.value=s.booked);document.querySelectorAll('[data-session-hours]').forEach(el=>el.textContent=Math.floor(s.booked/60)+'h '+String(s.booked%60).padStart(2,'0')+'m');document.querySelectorAll('[data-planning-finish]').forEach(el=>el.value=proposalClockTime(end.getTime()));syncAutomaticPlanDisplay(s);}
document.addEventListener('toggle',event=>{if(!event.target.matches('.session-planning-menu'))return;unifiedState.planningOpen=event.target.open;if(event.target.open){closeMeasurePickers();closePlannedPickers();}positionPlanningMenu();},true);
document.addEventListener('click',event=>{const summary=event.target.closest('.session-planning-menu>summary');if(summary){unifiedState.planningOpen=!summary.parentElement.open;return;}const extend=event.target.closest('[data-extend-session]');if(extend){setProposalBudget(unifiedState,Math.min(1440,unifiedState.booked+Number(extend.dataset.extendSession)));unifiedState.scoreWorkflowClock.fixedEndAt=unifiedState.scoreWorkflowClock.plannedEndAt;return;}const menu=document.querySelector('.session-planning-menu[open]');if(menu&&!event.target.closest('.session-planning-menu')&&!event.target.closest('[data-main-layout]')){menu.open=false;unifiedState.planningOpen=false;}});
document.addEventListener('keydown',event=>{const menu=document.querySelector('.session-planning-menu[open]');if(event.key==='Escape'&&menu){event.preventDefault();menu.open=false;unifiedState.planningOpen=false;menu.querySelector('summary').focus({preventScroll:true});}if(event.key==='Enter'&&event.target.matches('[data-planning-finish]')&&!event.metaKey){event.preventDefault();event.target.blur();}});
function applyPlanningFinish(input,s=unifiedState){
 const value=parseLocalClock(input.value);if(!value){input.setCustomValidity('Use a clock time, for example 05:30 PM.');input.reportValidity();return false;}input.setCustomValidity('');
 const timing=scoreWorkflowTiming(s),anchor=timing.clock.plannedEndAt-timing.clock.booked*1000,target=new Date(anchor);target.setHours(value.hours,value.minutes,0,0);if(target.getTime()<=anchor)target.setDate(target.getDate()+1);
 setProposalBudget(s,Math.max(15,Math.min(1440,Math.ceil((target.getTime()-anchor)/60000))));s.scoreWorkflowClock.fixedEndAt=s.scoreWorkflowClock.plannedEndAt;return true;
}
 document.addEventListener('change',event=>{if(event.target.matches('[data-planning-finish]'))applyPlanningFinish(event.target);});
addEventListener('resize',positionPlanningMenu);document.addEventListener('scroll',positionPlanningMenu,true);
const proposalAvailableCues=[['1M04','Pool Flashback','01:15'],['1M08','Beach','00:47'],['1M12','Bankruptcy','01:29'],['1M19','52 Uur Eerder','02:11'],['1M25','Cave Talk','00:49'],['1M29','Harry Arrives','01:30'],['1M39','Wanted','01:55']];
function appDialog(title,content,actions=''){
 document.querySelector('.app-dialog')?.remove();const dialog=document.createElement('dialog');dialog.className='app-dialog';dialog.lang='en';dialog.innerHTML=`<header><h2>${title}</h2><button data-app-dialog-close aria-label="Close">×</button></header>${content}<footer><button data-app-dialog-close>Cancel</button>${actions}</footer>`;document.body.append(dialog);dialog.showModal();dialog.addEventListener('close',()=>dialog.remove(),{once:true});return dialog;
}
function openAddSessionCues(){
 const available=proposalAvailableCues.filter(c=>!cues.some(x=>x[0]===c[0]));
 appDialog('Add cues to this session',`<label class="add-cues-all"><input type="checkbox" data-add-cues-all> Select all (${available.length})</label><div class="add-cue-options">${available.map(c=>`<label><input type="checkbox" data-add-session-cue="${c[0]}"><b>${c[0]}</b><span>${esc(c[1])}</span><small>${c[2]}</small></label>`).join('')||'<p>All available cues are already in this session.</p>'}</div>`, '<button data-app-action="confirm-cues" disabled>Add cues</button>');
}
function renderSessionChat(){
 const s=unifiedState;document.querySelector('.session-chat')?.remove();if(!s.chatOpen)return;
 const panel=document.createElement('aside');panel.className='session-chat';panel.lang='en';panel.setAttribute('aria-label','Session chat');panel.innerHTML=`<header><b>${appIcon('chat')} Session chat</b><button data-app-action="chat" aria-label="Close session chat">×</button></header><div class="session-chat-messages">${(s.chatMessages||[]).map(m=>`<p><small>${esc(m.cue)} · ${esc(m.take)} · ${esc(m.time)}</small>${esc(m.text)}</p>`).join('')}</div><form data-session-chat-form><label>Message everyone<textarea aria-label="Session chat message" placeholder="Message everyone…"></textarea></label><button>Send</button></form>`;document.body.append(panel);
}
function sessionTakeLog(s=unifiedState){
 return {format:'mandocues-take-log-v1',demo:true,exportedAt:new Date().toISOString(),sessionId:s.sessionId,sessionLabel:proposalSessionMeta(s).label,takes:s.takes.flatMap((takes,j)=>takes.map(t=>({takeId:t.id,cueCode:t.takeLog?.cueCode??(s===unifiedState?cues:s.sessionCues)?.[j]?.[0]??null,number:t.num,kind:t.kind,label:t.label||'',log:t.takeLog?{...t.takeLog}:null,durationSeconds:t.rolling?position(t):t.duration,notes:t.notes.map(n=>({id:n.id,text:n.text,bar:n.measureScope==='all'?null:n.measure??null,barScope:n.measureScope||'bar',clockAt:Number.isFinite(n.clockAt)?new Date(n.clockAt).toISOString():null}))})))};
}
function takeLoggedTime(t){const stamp=value=>new Date(value).toLocaleString('en-US',{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true,timeZoneName:'short'});return t.takeLog?`Logged start ${esc(stamp(t.takeLog.loggedStartAt))}${t.takeLog.loggedEndAt?' · Logged stop '+esc(stamp(t.takeLog.loggedEndAt)):' · In progress'}`:'Recording time not logged (example take)';}
function openSessionExport(kind){
 document.querySelectorAll('.session-pdf-menu').forEach(el=>el.open=false);
 const body=kind==='takes'?cues.map((c,j)=>`<h3>${c[0]} ${esc(c[1])}</h3>${unifiedState.takes[j].map(t=>`<section><b>${entryLabel(t)}</b>${t.label?` · ${esc(t.label)}`:""} · ${t.rating||'—'}/5${t.best?' · Best':''}<p><small>${takeLoggedTime(t)}</small></p><ul>${t.notes.map(n=>`<li>${esc(n.text)} · ${n.measureScope==='all'?'All':n.measure?'Bar '+n.measure:'—'} · ${noteTimeValue(n)}</li>`).join('')}</ul></section>`).join('')}`).join(''):`<table><thead><tr><th>Cue</th><th>Title</th><th>Music length</th><th>Planned (min)</th></tr></thead><tbody>${cues.map((c,j)=>`<tr><td>${c[0]}</td><td>${esc(c[1])}</td><td>${c[2]}</td><td>${cuePlannedMinutes(j)}</td></tr>`).join('')}</tbody></table>`;
 appDialog(kind==='takes'?'Take sheet':'Recording order',`<div class="session-export-preview">${body}</div>`,`${kind==='takes'?'<button data-app-action="download-take-log">Download take log (JSON)</button>':''}<button data-app-action="print-export">Print / Save as PDF</button>`);
}
document.addEventListener('click',event=>{
 const close=event.target.closest('[data-app-dialog-close]');if(close){close.closest('dialog').close();return;}
 const exp=event.target.closest('[data-app-export]');if(exp){openSessionExport(exp.dataset.appExport);return;}
 const action=event.target.closest('[data-app-action]')?.dataset.appAction;if(!action)return;
 if(action==='add-cues')openAddSessionCues();
 if(action==='chat'){unifiedState.chatOpen=!unifiedState.chatOpen;document.querySelector('[data-app-action="chat"][aria-pressed]')?.setAttribute('aria-pressed',unifiedState.chatOpen);renderSessionChat();}
 if(action==='print-export')window.print();
 if(action==='download-take-log')saveFile('MandoCues-take-log.json',JSON.stringify(sessionTakeLog(),null,2),'application/json;charset=utf-8');
 if(action==='confirm-cues'){
  const selected=[...document.querySelectorAll('[data-add-session-cue]:checked')].map(el=>el.dataset.addSessionCue);
  for(const code of selected){const cue=proposalAvailableCues.find(c=>c[0]===code);if(!cue||cues.some(c=>c[0]===code))continue;cues.push([...cue]);unifiedState.takes.push([]);unifiedState.cueNotes.push([]);unifiedState.cueDrafts.push('');}
  document.querySelector('.app-dialog').close();renderDemo();
 }
});
document.addEventListener('change',event=>{
 if(event.target.matches('[data-add-cues-all]'))document.querySelectorAll('[data-add-session-cue]').forEach(el=>el.checked=event.target.checked);
 if(event.target.matches('[data-add-cues-all],[data-add-session-cue]'))document.querySelector('[data-app-action="confirm-cues"]').disabled=!document.querySelector('[data-add-session-cue]:checked');
 const key=event.target.dataset.sessionSetting;if(!key)return;const value=+event.target.value;
 if(!event.target.checkValidity()||!Number.isFinite(value))return;
 if(key==='length')setProposalBudget(unifiedState,value);
 if(key==='prep')unifiedState.prepMinutes=value;
 if(key==='music'){unifiedState.maxMusicMinutes=value;syncMusicUsage(unifiedState);}
 syncAutomaticPlanDisplay(unifiedState);
});
document.addEventListener('submit',event=>{
 if(!event.target.matches('[data-session-chat-form]'))return;event.preventDefault();const field=event.target.querySelector('textarea'),text=field.value.trim();if(!text)return;
 const s=unifiedState,t=running(s)||takeById(s,s.selected);s.chatMessages??=[];s.chatMessages.push({text,cue:cues[s.cue][0],take:t?entryLabel(t):'',time:proposalClockTime(Date.now())});renderSessionChat();document.querySelector('[data-session-chat-form] textarea')?.focus();
});
